/* ------------------------------------------------------------------ metrics */

const metricFilter = { route: '', sort: 'requests' };

/**
 * Line chart in SVG (no library): one or more series over time, with the maximum and the last
 * value as text, and a table alternative for screen readers.
 */
function lineChart(title, points, series, unit) {
  const width = 360;
  const height = 120;
  const pad = 4;
  const values = points.flatMap((p) => series.map((s) => p[s.key])).filter((v) => typeof v === 'number');
  const max = Math.max(1, ...values);
  const minTs = points.length ? points[0].ts : 0;
  const maxTs = points.length ? points[points.length - 1].ts : 1;
  const x = (ts) => pad + ((ts - minTs) / Math.max(1, maxTs - minTs)) * (width - 2 * pad);
  const y = (v) => height - pad - (v / max) * (height - 2 * pad);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('class', 'obs-line');
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', `${title}, maximum ${Math.round(max * 10) / 10}${unit}`);
  series.forEach((s, i) => {
    const d = points.filter((p) => typeof p[s.key] === 'number')
      .map((p, j) => `${j ? 'L' : 'M'}${x(p.ts).toFixed(1)},${y(p[s.key]).toFixed(1)}`).join(' ');
    if (!d) return;
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', d);
    path.setAttribute('class', `obs-line-${i}`);
    svg.append(path);
  });
  const last = points.length ? points[points.length - 1] : {};
  return h('figure', { class: 'obs-chart' },
    h('figcaption', {}, h('strong', {}, title), ' ',
      series.map((s, i) => h('span', { class: `obs-legend obs-legend-${i}` }, `${s.label} ${last[s.key] ?? '—'}${unit}`))),
    svg);
}

const VITAL_LIMITS = { LCP: [2500, 4000], INP: [200, 500], CLS: [0.1, 0.25], FCP: [1800, 3000], TTFB: [800, 1800] };

function vitalsTable(vitals) {
  if (!vitals.length) return null;
  const tone = (v) => {
    const [good, poor] = VITAL_LIMITS[v.name] || [Infinity, Infinity];
    return v.p75 === null ? '' : v.p75 <= good ? 'obs-ok' : v.p75 <= poor ? '' : 'obs-err';
  };
  return [h('h2', {}, 'Web Vitals (p75)'), h('table', { class: 'obs-table' },
    h('thead', {}, h('tr', {}, h('th', {}, 'Page'), h('th', {}, 'Vital'), h('th', {}, 'p75'), h('th', {}, 'Poor'),
      h('th', { class: 'obs-hide-sm' }, 'Samples'), h('th', { class: 'obs-hide-sm' }, 'Source'))),
    h('tbody', {}, vitals.map((v) => h('tr', {},
      h('td', { class: 'obs-mono' }, v.page), h('td', {}, v.name),
      h('td', { class: `obs-mono ${tone(v)}` }, v.p75 === null ? '—' : v.name === 'CLS' ? v.p75 : `${v.p75} ms`),
      h('td', { class: `obs-mono${v.poorRate > 0 ? ' obs-err' : ''}` }, `${v.poorRate} %`),
      h('td', { class: 'obs-hide-sm obs-mono' }, v.samples), h('td', { class: 'obs-hide-sm' }, v.src)))))];
}

function metricsView() {
  load(({ vitals, ...data }) => {
    const points = data.series || [];
    const routeFilter = metricFilter.route
      ? h('p', {}, 'Route ', h('code', {}, metricFilter.route), ' ',
        h('button', { onclick: () => { metricFilter.route = ''; navigate(); } }, 'All routes'))
      : null;
    return [
      routeFilter,
      points.length ? h('div', { class: 'obs-charts' },
        lineChart('Requests / min', points, [{ key: 'rpm', label: '' }], ''),
        lineChart('Errors', points, [{ key: 'errorRate', label: '' }], ' %'),
        lineChart('Latency', points, [{ key: 'p50', label: 'p50' }, { key: 'p95', label: 'p95' }, { key: 'p99', label: 'p99' }], ' ms'))
        : empty('No requests in this range (the metrics count the SERVER spans)'),
      h('h2', {}, 'Routes ', h('select', { 'aria-label': 'Sort routes', onchange: (e) => { metricFilter.sort = e.target.value; navigate(); } },
        [['requests', 'by requests'], ['p95', 'by p95 (slowest)'], ['totalMs', 'by total time']]
          .map(([value, label]) => h('option', { value, selected: metricFilter.sort === value }, label)))),
      (data.routes || []).length ? h('table', { class: 'obs-table' },
        h('thead', {}, h('tr', {}, h('th', {}, 'Route'), h('th', { class: 'obs-hide-sm' }, 'Source'), h('th', {}, 'Req/min'),
          h('th', {}, 'Errors'), h('th', { class: 'obs-hide-sm' }, 'p50'), h('th', {}, 'p95'), h('th', { class: 'obs-hide-sm' }, 'p99'),
          h('th', { class: 'obs-hide-sm' }, 'Total'))),
        h('tbody', {}, [...data.routes].sort((a, b) => (b[metricFilter.sort] || 0) - (a[metricFilter.sort] || 0)).map((r) => h('tr', { class: 'obs-row', tabindex: 0,
          onclick: () => { metricFilter.route = r.route; navigate(); },
          onkeydown: (e) => { if (e.key === 'Enter') { metricFilter.route = r.route; navigate(); } } },
        h('td', { class: 'obs-mono' }, `${r.method ? `${r.method} ` : ''}${r.route}`),
        h('td', { class: 'obs-hide-sm' }, r.src),
        h('td', { class: 'obs-mono' }, r.rpm),
        h('td', { class: `obs-mono${r.errorRate > 0 ? ' obs-err' : ''}` }, `${r.errorRate} %`),
        h('td', { class: 'obs-hide-sm obs-mono' }, r.p50 ?? '—'),
        h('td', { class: 'obs-mono' }, r.p95 ?? '—'),
        h('td', { class: 'obs-hide-sm obs-mono' }, r.p99 ?? '—'),
        h('td', { class: 'obs-hide-sm obs-mono' }, r.totalMs ? fmtDuration(r.totalMs) : '—'))))) : null,
      vitalsTable(vitals || []),
    ];
  }, async () => {
    const [data, vitals] = await Promise.all([api('/metrics', { src: state.src, route: metricFilter.route, ...range() }),
      api('/vitals', { src: state.src, ...range() }).catch(() => [])]);
    return { ...data, vitals };
  });
}

/* ------------------------------------------------------------------ service map */

/**
 * Layered map (SVG, no library): client applications on the left, apis in the middle, databases,
 * queues and external hosts on the right. The width of an edge grows with its traffic and it is red
 * when it has errors; its label shows calls per minute and p95.
 */
function mapView() {
  load((data) => {
    const edges = data.edges || [];
    if (!edges.length) return empty('No calls in this range (the map comes from the CLIENT spans)');
    const kinds = Object.fromEntries((state.sources || []).map((s) => [s.code, s.originType === 'app' ? 0 : 1]));
    const layer = (node) => (node in kinds ? kinds[node] : 2);
    const nodes = [...new Set(edges.flatMap((e) => [e.from, e.to]))];
    const columns = [[], [], []];
    nodes.forEach((node) => columns[layer(node)].push(node));
    columns.forEach((column) => column.sort());
    const width = 900;
    const rowHeight = 56;
    const height = Math.max(120, Math.max(...columns.map((c) => c.length)) * rowHeight + 40);
    const pos = {};
    columns.forEach((column, i) => column.forEach((node, j) => {
      pos[node] = { x: 90 + i * ((width - 180) / 2), y: 30 + j * rowHeight + rowHeight / 2 };
    }));
    const maxRpm = Math.max(1, ...edges.map((e) => e.rpm || 0));
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('class', 'obs-map');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', `Service map: ${nodes.length} nodes, ${edges.length} edges`);
    const el = (tag, attrs, text) => {
      const node = document.createElementNS(ns, tag);
      Object.entries(attrs).forEach(([k, v]) => node.setAttribute(k, String(v)));
      if (text !== undefined) node.textContent = text;
      svg.append(node);
      return node;
    };
    for (const edge of edges) {
      const a = pos[edge.from];
      const b = pos[edge.to];
      const line = el('line', { x1: a.x + 70, y1: a.y, x2: b.x - 70, y2: b.y,
        class: `obs-map-edge${edge.errorRate > 0 ? ' error' : ''}`, 'stroke-width': 1 + 5 * ((edge.rpm || 0) / maxRpm) });
      el('title', {}, `${edge.from} → ${edge.to}: ${edge.rpm}/min, ${edge.errorRate} % errors, p95 ${edge.p95 ?? '—'} ms`);
      line.append(svg.lastChild);
      el('text', { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 - 4, class: 'obs-map-label', 'text-anchor': 'middle' },
        `${edge.rpm}/min · p95 ${edge.p95 ?? '—'} ms${edge.errorRate > 0 ? ` · ${edge.errorRate} %` : ''}`);
    }
    for (const node of nodes) {
      const p = pos[node];
      el('rect', { x: p.x - 70, y: p.y - 16, width: 140, height: 32, rx: 6, class: `obs-map-node layer-${layer(node)}` });
      el('text', { x: p.x, y: p.y + 4, 'text-anchor': 'middle', class: 'obs-map-name' }, node.length > 20 ? `${node.slice(0, 19)}…` : node);
    }
    return [
      h('p', { class: 'obs-muted' }, 'Applications · APIs · dependencies. Hover an edge for its metrics.'),
      h('div', { class: 'obs-map-wrap' }, svg),
      h('h2', {}, 'Calls'),
      h('table', { class: 'obs-table' },
        h('thead', {}, h('tr', {}, h('th', {}, 'From'), h('th', {}, 'To'), h('th', {}, 'Calls/min'), h('th', {}, 'Errors'), h('th', {}, 'p95'))),
        h('tbody', {}, edges.map((e) => h('tr', {}, h('td', {}, e.from), h('td', { class: 'obs-mono' }, e.to),
          h('td', { class: 'obs-mono' }, e.rpm), h('td', { class: `obs-mono${e.errorRate > 0 ? ' obs-err' : ''}` }, `${e.errorRate} %`),
          h('td', { class: 'obs-mono' }, e.p95 ?? '—'))))),
    ];
  }, async () => {
    if (!state.sources?.length) state.sources = await api('/sources');
    return api('/map', { src: state.src, ...range() });
  });
}

/* ------------------------------------------------------------------ issue detail */

/** Bars of the occurrences per hour (SVG, no library): one bar per bucket, scaled to the maximum. */
function histogramChart(histogram) {
  const counts = histogram.counts || [];
  const max = Math.max(1, ...counts);
  const width = 720;
  const height = 80;
  const bar = width / Math.max(1, counts.length);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('class', 'obs-histogram');
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', `Occurrences per hour, last ${Math.round(counts.length / 24)} days, maximum ${max}`);
  counts.forEach((count, i) => {
    if (!count) return;
    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    const h = Math.max(2, (count / max) * (height - 4));
    rect.setAttribute('x', String(i * bar));
    rect.setAttribute('y', String(height - h));
    rect.setAttribute('width', String(Math.max(1, bar - 1)));
    rect.setAttribute('height', String(h));
    const title = document.createElementNS('http://www.w3.org/2000/svg', 'title');
    title.textContent = `${new Date(histogram.from + i * histogram.bucketMs).toLocaleString()}: ${count}`;
    rect.append(title);
    svg.append(rect);
  });
  return svg;
}

/** The stack with the own frames highlighted and the runs of library frames folded. */
function stackView(lines) {
  if (!lines || !lines.length) return h('p', { class: 'obs-muted' }, 'No stack trace for this event.');
  const out = [];
  let folded = [];
  const flush = () => {
    if (folded.length) {
      out.push(h('details', { class: 'obs-stack-lib' }, h('summary', {}, `${folded.length} library frames`),
        folded.map((line) => h('div', {}, line.text))));
      folded = [];
    }
  };
  for (const line of lines) {
    if (line.frame && !line.inApp) {
      folded.push(line);
    } else {
      flush();
      out.push(h('div', { class: line.inApp ? 'obs-stack-own' : '' }, line.text));
    }
  }
  flush();
  return h('div', { class: 'obs-stack obs-mono' }, out);
}

function distributionView(distribution) {
  const labels = { release: 'Release', environment: 'Environment', browser: 'Browser', tenant: 'Tenant' };
  return h('div', { class: 'obs-distribution' }, Object.entries(distribution || {}).map(([field, values]) =>
    h('div', {}, h('h3', {}, labels[field] || field), values.length ? h('ul', {}, values.map((v) =>
      h('li', {}, h('span', { class: 'obs-mono' }, v.value), ' ', h('span', { class: 'obs-muted' }, v.count)))) : empty('—'))));
}

function issueView(uid) {
  let index = 0;
  load((detail) => {
    const issue = detail.issue;
    const events = detail.events || [];
    const eventBox = h('div', { class: 'obs-event' });
    const showEvent = () => {
      const event = events[index];
      if (!event) {
        eventBox.replaceChildren(empty('No stored events (they may be out of the retention)'));
        return;
      }
      eventBox.replaceChildren(
        h('div', { class: 'obs-filters' },
          h('button', { disabled: index === 0, onclick: () => { index--; showEvent(); } }, '‹ Newer'),
          h('span', { class: 'obs-muted' }, ` Event ${index + 1} of ${events.length} · ${fmtTime(event.log.ts)} `),
          h('button', { disabled: index >= events.length - 1, onclick: () => { index++; showEvent(); } }, 'Older ›'),
          event.log.traceId ? [' ', h('a', { href: `#/traces/${event.log.traceId}` }, 'Open its trace')] : null),
        h('p', { class: 'obs-msg' }, event.log.msg),
        contextCard(event.log),
        stackView(event.stack));
    };
    showEvent();
    const write = canWrite();
    return [
      h('p', {}, h('a', { href: '#/issues' }, '← Issues')),
      h('h1', { class: 'obs-issue-title' }, h('span', { class: issue.level === 'FATAL' || issue.level === 'ERROR' ? 'obs-err' : 'obs-muted' }, '● '), issue.title),
      issue.culprit ? h('p', { class: 'obs-muted obs-mono' }, issue.culprit) : null,
      h('div', { class: 'obs-filters' }, h('span', { class: 'obs-chip' }, issue.status.toLowerCase()),
        issue.mergedInto ? h('a', { href: `#/issues/${issue.mergedInto}` }, 'merged into another issue') : null,
        issue.assignee ? h('span', { class: 'obs-chip' }, `@${issue.assignee}`) : null,
        issue.ignoreUntil ? h('span', { class: 'obs-muted' }, `ignored until ${fmtTime(issue.ignoreUntil)}`) : null,
        issue.ignoreUntilCount ? h('span', { class: 'obs-muted' }, `ignored until ${issue.ignoreUntilCount} events`) : null,
        issue.trackerUrl ? h('a', { href: issue.trackerUrl, target: '_blank', rel: 'noopener' }, 'Task') : null,
        ...(write ? (ISSUE_ACTIONS[issue.status] || []).map((action) => [' ',
          h('button', { onclick: (e) => issueAction(issue, action, e.target) }, ACTION_LABELS[action])]) : []),
        ...(write && issue.status !== 'MERGED' ? workflowButtons(issue) : [])),
      h('dl', { class: 'obs-context' },
        h('dt', {}, 'Source'), h('dd', {}, issue.source || ''),
        h('dt', {}, 'Events'), h('dd', { class: 'obs-mono' }, issue.count),
        h('dt', {}, 'Users / tenants'), h('dd', { class: 'obs-mono' }, `${issue.users || 0} / ${issue.tenants || 0}`),
        h('dt', {}, 'First seen'), h('dd', { class: 'obs-mono' }, issue.firstSeenAt ? fmtTime(issue.firstSeenAt) : '—'),
        h('dt', {}, 'Last seen'), h('dd', { class: 'obs-mono' }, issue.lastSeenAt ? fmtTime(issue.lastSeenAt) : '—'),
        h('dt', {}, 'Releases'), h('dd', { class: 'obs-mono' }, [issue.firstRelease, issue.release].filter(Boolean).join(' → ') || '—')),
      h('h2', {}, 'Occurrences (last 7 days, per hour)'), histogramChart(detail.histogram),
      h('h2', {}, 'Events'), eventBox,
      h('h2', {}, `Distribution (${detail.sampled} stored events)`), distributionView(detail.distribution),
      h('h2', {}, 'Comments'), ...[commentsView(issue, detail.comments || [])].flat(),
    ];
  }, async () => {
    const [detail, comments] = await Promise.all([api(`/issues/${encodeURIComponent(uid)}`),
      api(`/issues/${encodeURIComponent(uid)}/comments`).catch(() => [])]);
    return { ...detail, comments };
  });
}

/** Runs a workflow call and renders again; its error is shown in a gate. */
async function workflow(path, params, button, body) {
  if (button) button.disabled = true;
  try {
    const result = await api(path, params, true, 'POST', body);
    if (result && result.url && path.endsWith('/ticket')) window.open(result.url, '_blank', 'noopener');
    render();
  } catch (error) {
    if (button) button.disabled = false;
    gate('Unable to change the issue', [h('p', {}, error.message)],
      [h('button', { class: 'primary', onclick: () => { shell(); render(); } }, 'Back')]);
  }
}

function workflowButtons(issue) {
  const base = `/issues/${encodeURIComponent(issue.uid)}`;
  return [' ',
    issue.assignee === state.me?.user
      ? h('button', { onclick: (e) => workflow(`${base}/assign`, { me: '0' }, e.target) }, 'Unassign')
      : h('button', { onclick: (e) => workflow(`${base}/assign`, {}, e.target) }, 'Assign to me'),
    ' ', h('button', { onclick: (e) => {
      const hours = prompt('Ignore for how many hours? (empty: no time limit)', '24');
      if (hours === null) return;
      const events = prompt('…or until how many more events? (empty: no count limit)', '');
      if (events === null) return;
      workflow(`${base}/snooze`, { hours: hours || '', events: events || '' }, e.target);
    } }, 'Snooze…'),
    ' ', h('button', { onclick: (e) => {
      const into = prompt('Merge into the issue (paste its uid, from its link #/issues/<uid>)');
      if (into) workflow(`${base}/merge`, { into: into.replace(/.*#\/issues\//, '').trim() }, e.target);
    } }, 'Merge into…'),
    ' ', h('button', { onclick: (e) => {
      const pattern = prompt('Regular expression of the messages that go to a separate issue');
      if (pattern) workflow(`${base}/split`, { pattern }, e.target);
    } }, 'Split…'),
    ' ', issue.trackerUrl ? null : h('button', { onclick: (e) => workflow(`${base}/ticket`, {}, e.target) }, 'Create task')];
}

function commentsView(issue, comments) {
  const list = comments.length ? h('ul', { class: 'obs-comments' }, comments.map((c) =>
    h('li', {}, h('div', { class: 'obs-muted' }, `${c.authorName} · ${fmtTime(c.createdAt)}`), h('div', { class: 'obs-comment-text' }, c.text))))
    : empty('No comments');
  if (!canWrite()) return list;
  const text = h('textarea', { rows: 3, 'aria-label': 'New comment', placeholder: 'Findings, links, decisions…' });
  return [list, h('form', { class: 'obs-comment-form', onsubmit: (e) => {
    e.preventDefault();
    if (text.value.trim()) workflow(`/issues/${encodeURIComponent(issue.uid)}/comments`, {}, e.submitter, text.value);
  } }, text, h('button', { class: 'primary', type: 'submit' }, 'Comment'))];
}

/* ------------------------------------------------------------------ slos and uptime */

function pct(value, digits = 2) {
  return value === null || value === undefined ? '—' : `${Number(value).toFixed(digits)} %`;
}

/** Objectives: compliance of the window, remaining error budget and burn rates. */
function slosView() {
  load((slos) => slos.length ? h('table', { class: 'obs-table' },
    h('thead', {}, h('tr', {}, h('th', {}, 'Objective'), h('th', {}, 'Target'), h('th', {}, 'Compliance'),
      h('th', {}, 'Error budget'), h('th', { class: 'obs-hide-sm' }, 'Burn 1 h / 6 h'))),
    h('tbody', {}, slos.map((slo) => {
      const budget = Math.max(-1, Math.min(1, slo.budget));
      const burning = slo.fastBurn || slo.slowBurn;
      return h('tr', {},
        h('td', {}, h('strong', {}, slo.name), h('div', { class: 'obs-muted obs-mono' },
          `${slo.source}${slo.route ? ` ${slo.route}` : ''} · ${slo.kind} · ${slo.windowDays} d`)),
        h('td', { class: 'obs-mono' }, pct(slo.objective * 100, 1)),
        h('td', { class: `obs-mono${slo.compliance !== null && slo.compliance < slo.objective ? ' obs-err' : ''}` },
          slo.compliance === null ? '—' : pct(slo.compliance * 100, 3)),
        h('td', {}, h('div', { class: 'obs-meter', role: 'meter', 'aria-valuemin': -100, 'aria-valuemax': 100, 'aria-valuenow': Math.round(budget * 100) },
          h('div', { class: `obs-meter-bar${budget < 0.25 ? ' high' : ''}`, style: `width:${Math.max(0, Math.round(budget * 100))}%` })),
          h('span', { class: 'obs-mono obs-muted' }, pct(budget * 100, 1))),
        h('td', { class: `obs-hide-sm obs-mono${burning ? ' obs-err' : ''}` },
          `${slo.burn1h.toFixed(1)}x / ${slo.burn6h.toFixed(1)}x${burning ? ' · burning' : ''}`));
    }))) : empty('No objectives: create them in observed-slo (they are evaluated every minute)'),
  () => api('/slos'));
}

/** Probes: state of the last check, latency, availability of 7 and 30 days and TLS expiration. */
function uptimeView() {
  load((probes) => probes.length ? h('table', { class: 'obs-table' },
    h('thead', {}, h('tr', {}, h('th', {}, 'Probe'), h('th', {}, 'State'), h('th', { class: 'obs-hide-sm' }, 'Latency'),
      h('th', {}, '7 d'), h('th', { class: 'obs-hide-sm' }, '30 d'), h('th', { class: 'obs-hide-sm' }, 'TLS expires'),
      h('th', { class: 'obs-hide-sm' }, 'Last check'))),
    h('tbody', {}, probes.map((probe) => h('tr', {},
      h('td', {}, h('strong', {}, probe.name), h('div', { class: 'obs-muted obs-mono' }, probe.url)),
      h('td', {}, probe.up ? h('span', { class: 'obs-ok' }, '● Up') : h('span', { class: 'obs-err', title: probe.error || '' }, `● Down${probe.error ? `: ${probe.error}` : ''}`)),
      h('td', { class: 'obs-hide-sm obs-mono' }, `${probe.latencyMs} ms`),
      h('td', { class: 'obs-mono' }, pct(probe.availability7d)),
      h('td', { class: 'obs-hide-sm obs-mono' }, pct(probe.availability30d)),
      h('td', { class: 'obs-hide-sm obs-mono obs-muted' }, probe.tlsExpiresAt ? new Date(probe.tlsExpiresAt).toLocaleDateString() : '—'),
      h('td', { class: 'obs-hide-sm obs-muted' }, ago(probe.checkedAt))))))
    : empty('No probes running: create them in observed-probe (only the allowed hosts are called)'),
  () => api('/probes'));
}

/* ------------------------------------------------------------------ insights */

const METRIC_LABELS = { rpm: 'Requests / min', errorRate: 'Error rate %', p95: 'p95 latency ms' };

/**
 * What is unusual now: metrics of a source out of what is usual for this hour, and log patterns
 * (WARN and above) never seen before the range.
 */
function insightsView() {
  load((data) => [
    h('h2', {}, 'Anomalies now'),
    (data.anomalies || []).length ? h('table', { class: 'obs-table' },
      h('thead', {}, h('tr', {}, h('th', {}, 'Source'), h('th', {}, 'Metric'), h('th', {}, 'Now'), h('th', {}, 'Usual'))),
      h('tbody', {}, data.anomalies.map((a) => h('tr', {},
        h('td', {}, a.source), h('td', {}, METRIC_LABELS[a.metric] || a.metric),
        h('td', { class: 'obs-mono obs-err' }, `${a.value} ${a.direction === 'up' ? '▲' : '▼'}`),
        h('td', { class: 'obs-mono obs-muted' }, `${a.mean} ± ${a.std}`)))))
      : empty('Nothing unusual (the baseline needs some days of metrics)'),
    h('h2', {}, 'New log patterns'),
    (data.patterns || []).length ? h('table', { class: 'obs-table' },
      h('thead', {}, h('tr', {}, h('th', {}, 'First seen'), h('th', {}, 'Level'), h('th', { class: 'obs-hide-sm' }, 'Source'),
        h('th', {}, 'Pattern'), h('th', { class: 'obs-hide-sm' }, 'Events'))),
      h('tbody', {}, data.patterns.map((p) => h('tr', { title: p.example || '' },
        h('td', { class: 'obs-mono obs-muted' }, fmtTime(p.firstSeen)),
        h('td', {}, h('span', { class: `obs-chip lvl-${p.level}` }, p.level)),
        h('td', { class: 'obs-hide-sm' }, p.src), h('td', { class: 'obs-mono obs-msg' }, p.template),
        h('td', { class: 'obs-hide-sm obs-mono' }, p.count)))))
      : empty('No new patterns in this range'),
  ], () => api('/insights', { from: range().from }));
}

/* ------------------------------------------------------------------ alerts */

const alertFilter = { status: '' };

/**
 * Alerts recorded by the rules (open first) and the rules with the state of their channel. The
 * rules are managed in the CRUD of observed-alert-rule (front generated or admin).
 */
function alertsView() {
  const status = h('select', { 'aria-label': 'Status', onchange: (e) => { alertFilter.status = e.target.value; navigate(); } },
    [['', 'All'], ['FIRING', 'Firing'], ['RESOLVED', 'Resolved']]
      .map(([value, label]) => h('option', { value, selected: alertFilter.status === value }, label)));
  load((data) => [
    h('div', { class: 'obs-filters' }, status),
    data.alerts.length ? alertTable(data.alerts) : empty('No alerts'),
    h('h2', {}, 'Rules'),
    data.rules.length ? ruleTable(data.rules) : empty('No alert rules: create them in observed-alert-rule'),
  ], () => api('/alerts', { status: alertFilter.status }));
}

function alertTable(alerts) {
  return h('table', { class: 'obs-table' },
    h('thead', {}, h('tr', {}, h('th', {}, 'Alert'), h('th', { class: 'obs-hide-sm' }, 'Rule'),
      h('th', {}, 'Fired'), h('th', { class: 'obs-hide-sm' }, 'Resolved'), h('th', { class: 'obs-hide-sm' }, 'Notified'))),
    h('tbody', {}, alerts.map((alert) => h('tr', {},
      h('td', {}, h('span', { class: alert.status === 'FIRING' ? 'obs-err' : 'obs-ok' }, '● '),
        alert.link ? h('a', { href: alert.link }, alert.summary) : alert.summary),
      h('td', { class: 'obs-hide-sm' }, alert.rule, alert.trigger ? h('div', { class: 'obs-muted obs-mono' }, alert.trigger) : null),
      h('td', { class: 'obs-mono obs-muted' }, fmtTime(alert.firedAt)),
      h('td', { class: 'obs-hide-sm obs-mono obs-muted' }, alert.resolvedAt ? fmtTime(alert.resolvedAt) : '—'),
      h('td', { class: 'obs-hide-sm obs-mono obs-muted' }, alert.notifiedAt ? fmtTime(alert.notifiedAt) : 'pending')))));
}

function ruleTable(rules) {
  return h('table', { class: 'obs-table' },
    h('thead', {}, h('tr', {}, h('th', {}, 'Rule'), h('th', {}, 'Trigger'), h('th', {}, 'Channel'), h('th', {}, 'State'))),
    h('tbody', {}, rules.map((rule) => h('tr', {},
      h('td', {}, rule.name), h('td', { class: 'obs-mono obs-muted' }, rule.trigger),
      h('td', {}, rule.channel, rule.channelAvailable ? null : h('span', { class: 'obs-err', title: 'No channel serves it (email needs multitenant-notification)' }, ' · not available')),
      h('td', {}, !rule.enabled ? h('span', { class: 'obs-muted' }, 'Disabled') : rule.muted ? h('span', { class: 'obs-muted' }, 'Muted') : h('span', { class: 'obs-ok' }, 'Active'))))));
}

/* ------------------------------------------------------------------ sources */

function ago(ts) {
  if (!ts) return '—';
  const minutes = Math.floor((Date.now() - ts) / 60000);
  if (minutes < 1) return 'just now';
  if (minutes < 60) return `${minutes} min ago`;
  if (minutes < 48 * 60) return `${Math.floor(minutes / 60)} h ago`;
  return `${Math.floor(minutes / 1440)} d ago`;
}

function bytes(value) {
  if (!value) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.min(units.length - 1, Math.floor(Math.log(value) / Math.log(1024)));
  return `${(value / 1024 ** i).toFixed(i ? 1 : 0)} ${units[i]}`;
}

/** The collector itself (ADMIN level): queue, writer, disk against its limit and last purge. */
function collectorCard(collector) {
  const max = (collector.maxDiskMb || 0) * 1024 * 1024;
  const ratio = max ? Math.min(1, collector.diskBytes / max) : 0;
  const statusClass = collector.status === 'UP' ? 'obs-ok' : 'obs-err';
  return h('section', { class: 'obs-card obs-collector', 'aria-label': 'Collector' },
    h('h2', {}, 'Collector ', h('span', { class: statusClass }, collector.status)),
    h('dl', { class: 'obs-context' },
      h('dt', {}, 'Queue'), h('dd', { class: 'obs-mono' }, `${collector.queueSize} / ${collector.capacity}`),
      h('dt', {}, 'Accepted / dropped'), h('dd', { class: 'obs-mono' }, `${collector.accepted} / ${collector.dropped}`,
        collector.droppedLastMinute ? h('span', { class: 'obs-err' }, ` (+${collector.droppedLastMinute} last min)`) : null),
      h('dt', {}, 'Write errors'), h('dd', { class: 'obs-mono' }, collector.writeErrors),
      h('dt', {}, 'Last batch'), h('dd', { class: 'obs-mono' }, collector.lastBatchAt ? `${collector.lastBatchSize} events in ${collector.lastBatchMillis} ms, ${ago(collector.lastBatchAt)}` : '—'),
      h('dt', {}, 'Disk'), h('dd', {}, h('div', { class: 'obs-meter', role: 'meter', 'aria-valuemin': 0, 'aria-valuemax': 100, 'aria-valuenow': Math.round(ratio * 100) },
        h('div', { class: `obs-meter-bar${ratio > 0.9 ? ' high' : ''}`, style: `width:${Math.round(ratio * 100)}%` })),
        h('span', { class: 'obs-mono obs-muted' }, `${bytes(collector.diskBytes)} of ${collector.maxDiskMb} MB`)),
      h('dt', {}, 'Last purge'), h('dd', { class: 'obs-mono' }, ago(collector.lastPurge))));
}

function sourcesView() {
  load(({ sources, health }) => {
    const activity = Object.fromEntries((health.sources || []).map((row) => [row.code, row]));
    const silent = (row) => row && row.silentMinutes !== null && row.expectedEveryMinutes && row.silentMinutes >= row.expectedEveryMinutes;
    return [
      health.collector ? collectorCard(health.collector) : null,
      sources.length ? h('table', { class: 'obs-table' },
        h('thead', {}, h('tr', {}, h('th', {}, 'Code'), h('th', {}, 'Name'), h('th', { class: 'obs-hide-sm' }, 'Type'),
          h('th', {}, 'State'), h('th', {}, 'Last event'), h('th', { class: 'obs-hide-sm' }, 'Events/min'),
          h('th', { class: 'obs-hide-sm' }, 'Dropped'), h('th', { class: 'obs-hide-sm' }, 'Release'),
          h('th', { class: 'obs-hide-sm' }, 'Ingest key'))),
        h('tbody', {}, sources.map((s) => {
          const row = activity[s.code] || {};
          return h('tr', {},
            h('td', { class: 'obs-mono' }, s.code), h('td', {}, s.name),
            h('td', { class: 'obs-hide-sm obs-muted' }, s.originType),
            h('td', {}, s.accepting ? h('span', { class: 'obs-ok' }, 'Accepting') : h('span', { class: 'obs-muted' }, 'Rejected')),
            h('td', { class: silent(row) ? 'obs-err' : 'obs-muted', title: row.expectedEveryMinutes ? `Expected every ${row.expectedEveryMinutes} min` : '' },
              ago(row.lastSeen || s.lastSeen), silent(row) ? ' · silent' : ''),
            h('td', { class: 'obs-hide-sm obs-mono' }, row.eventsPerMinute ?? '—'),
            h('td', { class: `obs-hide-sm obs-mono${row.dropped ? ' obs-err' : ''}` }, row.dropped ?? s.dropped ?? 0),
            h('td', { class: 'obs-hide-sm obs-mono obs-muted' }, s.release || row.release || '—'),
            h('td', { class: 'obs-hide-sm obs-mono' }, s.ingestKey ? h('code', {}, s.ingestKey) : h('span', { class: 'obs-muted' }, 'Admin only')));
        }))) : empty('No sources'),
    ];
  }, async () => {
    const [sources, health] = await Promise.all([api('/sources'), api('/health')]);
    state.sources = sources;
    return { sources, health };
  });
}

// Last resort: an error nobody handled is shown instead of being lost in the console.
addEventListener('unhandledrejection', (event) => {
  gate('Unexpected error', [h('p', { class: 'obs-muted' }, event.reason?.message || String(event.reason))],
    [h('button', { class: 'primary', onclick: () => location.reload() }, 'Reload')]);
});

start();
